import re, subprocess, time, random, string, sys

def ref(text):
    data=text.encode('utf-8','replace').decode('utf-8','replace').lower()
    c={}
    for w in re.findall(r'[a-z]+', data): c[w]=c.get(w,0)+1
    top=sorted(c.items(), key=lambda kv:(-kv[1], kv[0]))[:10]
    return ''.join('%s %d\n' % (w,n) for w,n in top)

def run(b):
    p=subprocess.run([sys.executable,'wf.py'],input=b,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if p.returncode: raise SystemExit('wf failed: '+p.stderr.decode())
    return p.stdout.decode()

